import RNA, random, multiprocessing as mp
target='......(.((((.((((....(...((((.(....).))))...)))))..((......((((....)))))).)))).).....................'
n=len(target)
def worker(seed):
    random.seed(seed)
    for _ in range(50):
        start=''.join(random.choice('ACGU') for _ in range(n))
        seq,d=RNA.inverse_fold(start,target)
        if d==0 and RNA.fold_compound(seq).mfe()[0]==target:
            return seq
    return None
if __name__=='__main__':
    with mp.Pool(20) as p:
        for r in p.imap_unordered(worker, range(400)):
            if r:
                print('SOLVED',r)
                p.terminate(); break
